fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // Since we assume arr1 and arr2 have the same length,
    // we can directly compare them element by element.
    // The `all` iterator adapter returns true if the predicate
    // holds for every paired element. For empty arrays, `all`
    // returns true by definition.
    arr1.iter().zip(arr2.iter()).all(|(a, b)| a > b)
}

